(async()=>{const f=document.createElement('iframe');document.body.append(f);await new Promise(r=>setTimeout(r,50));const c=f.contentWindow,s=localStorage;globalThis.shared=s;c.shared=s;s.clear();s.setItem('full','v'.repeat(5*1024*1024));const rows=[],capture=(label,fn)=>{try{fn();rows.push({label,unexpected:true})}catch(e){rows.push({label,name:e.name,message:e.message,parent:e instanceof DOMException,child:e instanceof c.DOMException})}};capture('parent-method',()=>Storage.prototype.setItem.call(s,'over','v'));capture('child-method',()=>c.Storage.prototype.setItem.call(s,'over','v'));capture('parent-write',()=>{s.over='v'});capture('child-write',()=>c.eval("shared.over='v'"));capture('child-define',()=>c.eval("Object.defineProperty(shared,'over',{value:'v'})"));s.clear();f.remove();return rows})()
